import Breadcrumbs from '@jetbrains/ring-ui-built/components/breadcrumbs/breadcrumbs'
import {graphql, useFragment, usePreloadedQuery} from 'react-relay'
import type {EntryPointProps} from 'react-relay'

import {useRunningBuildUpdaterRelay} from '../../../hooks/relay/useRunningBuildUpdaterRelay'
import {useBuildStatusIconRelay} from '../../../hooks/useBuildStatusIcon'
import useFormatBuildNumber from '../../../hooks/useFormatBuildNumber'
import {getBuildHref, getBuildTypeHref, getProjectHref} from '../../../routes'
import {ROOT_PROJECT_ID} from '../../../types'
import {useDisplayDate} from '../../../utils/dateTimeUtils'
import BreadcrumbsLink from '../Breadcrumbs/BreadcrumbsLink/BreadcrumbsLink'
import BreadcrumbsDropdown from '../BreadcrumbsDropdown/BreadcrumbsDropdown'

import type {OverviewBreadcrumbsBuildFragment$key} from './__generated__/OverviewBreadcrumbsBuildFragment.graphql'
import type {OverviewBreadcrumbsBuildTypeFragment$key} from './__generated__/OverviewBreadcrumbsBuildTypeFragment.graphql'
import type {OverviewBreadcrumbsProjectFragment$key} from './__generated__/OverviewBreadcrumbsProjectFragment.graphql'
import type {OverviewBreadcrumbsQuery} from './__generated__/OverviewBreadcrumbsQuery.graphql'
import {query} from './OverviewBreadcrumbs.queries'

const projectFragment = graphql`
  fragment OverviewBreadcrumbsProjectFragment on ProjectRest {
    id
    name
    ancestorProjects {
      project {
        id
        name
      }
    }
  }
`
const buildTypeFragment = graphql`
  fragment OverviewBreadcrumbsBuildTypeFragment on BuildTypeRest {
    id
    name
    type
    project {
      ...OverviewBreadcrumbsProjectFragment
    }
  }
`

const buildFragment = graphql`
  fragment OverviewBreadcrumbsBuildFragment on Build {
    id
    state
    startDate
    queuedDate
    ...useFormatBuildNumberFragment
    ...useBuildStatusIconFragment
    ...useRunningBuildUpdaterRelayFragment
    buildType {
      ...OverviewBreadcrumbsBuildTypeFragment
    }
  }
`

type Queries = {
  main: OverviewBreadcrumbsQuery
}

export default function OverviewBreadcrumbs({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const {project, buildType, build} = usePreloadedQuery(query, queries.main)
  const buildData = useFragment<OverviewBreadcrumbsBuildFragment$key>(buildFragment, build ?? null)
  const {state, startDate, queuedDate} = buildData ?? {}
  const buildTypeData = useFragment<OverviewBreadcrumbsBuildTypeFragment$key>(
    buildTypeFragment,
    buildData?.buildType ?? buildType ?? null,
  )
  const projectData = useFragment<OverviewBreadcrumbsProjectFragment$key>(
    projectFragment,
    buildTypeData?.project ?? project ?? null,
  )
  const buildNumber = useFormatBuildNumber(buildData)
  const buildIcon = useBuildStatusIconRelay(buildData, true)
  const date = useDisplayDate(startDate ?? queuedDate, true)
  useRunningBuildUpdaterRelay(buildData)

  return (
    <Breadcrumbs>
      {projectData?.ancestorProjects?.project?.map(
        ({name, id}) =>
          id != null &&
          id !== ROOT_PROJECT_ID &&
          name != null && (
            <span key={id}>
              <BreadcrumbsLink to={getProjectHref(id)} name={name} />
              <BreadcrumbsDropdown projectId={id} />
            </span>
          ),
      )}
      {projectData?.id != null && projectData.name != null && (
        <span>
          <BreadcrumbsLink
            active={buildTypeData == null}
            to={getProjectHref(projectData.id)}
            name={projectData.name}
          />
          <BreadcrumbsDropdown projectId={projectData.id} />
        </span>
      )}
      {buildTypeData?.id != null && buildTypeData.name != null && (
        <span>
          <BreadcrumbsLink
            active={buildData == null}
            to={getBuildTypeHref(buildTypeData.id)}
            name={buildTypeData.name}
            leftIcon={buildTypeData.type === 'composite' ? 'buildType-composite' : 'buildType'}
          />
          <BreadcrumbsDropdown buildTypeId={buildTypeData.id} />
        </span>
      )}
      {buildData?.id != null && buildNumber != null && (
        <BreadcrumbsLink
          active
          to={getBuildHref(buildData.id, buildTypeData?.id)}
          name={`${state === 'queued' ? 'Queued' : `Build ${buildNumber}`}${date != null ? ` on ${date}` : ''}`}
          leftIcon={buildIcon}
        />
      )}
    </Breadcrumbs>
  )
}
export type OverviewBreadcrumbsComponent = typeof OverviewBreadcrumbs
